<?php require '../config.php';header('Content-Type: application/json');if(!$pdo){echo json_encode([]);exit;}$q=$_GET['q']??'';$ids=$_GET['ids']??'';if($ids){$a=array_values(array_filter(array_map('intval',explode(',',$ids))));if(!$a){echo '[]';exit;}$in=implode(',',array_fill(0,count($a),'?'));$s=$pdo->prepare("SELECT id,name,category,price,image FROM products WHERE id IN ($in)");$s->execute($a);echo json_encode($s->fetchAll());exit;}$s=$pdo->prepare('SELECT id,name,category,price,image FROM products WHERE name LIKE ? OR category LIKE ? ORDER BY featured DESC');$s->execute(["%$q%","%$q%"]);echo json_encode($s->fetchAll());
